"""Authoritative combat: firing, hit validation, damage, armor, reload, healing, grenades, elimination.

The server never takes a damage number from a client. A client (or bot) says where it aims and
which participant it thinks it is shooting; this module checks the weapon, magazine, cooldown,
range, line of sight against map blockers (spatial.blocker_index) and the aim cone, then computes damage itself.

Rules chosen here (development values, not original Rules of Survival behaviour):
- Healing is cancelled when the participant takes damage or starts a reload. Firing and throwing
  are refused while healing. Movement does not cancel healing.
- Reload loads rounds from backpack ammo on completion; with no ammo it fails. No unlimited ammo.
- The heal item is consumed on completion, not at start.
- Energy drink grants boost points; boost regenerates BOOST_REGEN health per second until spent.
- Headshots are server-rolled. Bots get one from their roll (roll < hit_chance * HEADSHOT_SHARE).
  A human shot passes headshot=None and, once it hits, rolls match.rng < HEADSHOT_SHARE, so
  humans and bots share one headshot rate. An explicit True/False is a trusted value (tests, or
  a future validated gateway); SoloEngine ignores the client's hint unless told to trust it.
- Range and damage falloff use 3D distance (x, y, z). Free fall is not shootable; a parachuter
  is, within 3D range. Bots perceive exactly the SHOOTABLE states (bots/perception.py).
- Line of sight is tested on the ground plane against map blockers (blockers have no height).
- Pending grenades and boost live in module tables keyed by match. The engine must call
  tick_grenades(match) every tick and clear_match(match) when a match is removed.
"""

import math
from dataclasses import dataclass

from solo_engine import items, loot
from solo_engine.geometry import distance, normalize
from solo_engine.model import LifeState, Participant, SoloMatch, Stance
from solo_engine.spatial import blocker_index

HEADSHOT_SHARE = 0.12  # share of hits that are headshots, for bots and humans alike
BOT_HEADSHOT_SHARE = HEADSHOT_SHARE  # older name
BOOST_REGEN = 1.0  # health per second while boost remains
SHOOTABLE = frozenset({LifeState.GROUNDED, LifeState.IN_VEHICLE, LifeState.PARACHUTE})
_SHOOTABLE = SHOOTABLE


@dataclass
class PendingGrenade:
    grenade_id: str
    owner_id: str
    item_id: str
    x: float
    y: float
    explode_at: float


_MatchKey = tuple[str, int]
_GRENADES: dict[_MatchKey, list[PendingGrenade]] = {}
_BOOST: dict[_MatchKey, dict[str, float]] = {}


def _key(match: SoloMatch) -> _MatchKey:
    return (match.match_id, id(match))


def clear_match(match: SoloMatch) -> None:
    """Forget pending grenades, boost and loot side tables for a removed match."""
    _GRENADES.pop(_key(match), None)
    _BOOST.pop(_key(match), None)
    loot.clear_match(match)


def pending_grenades(match: SoloMatch) -> list[PendingGrenade]:
    return list(_GRENADES.get(_key(match), ()))


def boost_of(match: SoloMatch, p: Participant) -> float:
    return _BOOST.get(_key(match), {}).get(p.participant_id, 0.0)


# --------------------------------------------------------------------------- helpers


def distance3d(a: Participant, b: Participant) -> float:
    """Straight-line distance between two participants, altitude included."""
    return math.sqrt((a.x - b.x) ** 2 + (a.y - b.y) ** 2 + (a.z - b.z) ** 2)


def _active(p: Participant):
    inv = p.inventory
    if inv.active_slot is None or not 0 <= inv.active_slot < len(inv.weapons):
        return None
    return inv.weapons[inv.active_slot]


def _can_act(match: SoloMatch, p: Participant) -> bool:
    if not p.alive:
        return False
    if p.life == LifeState.GROUNDED:
        return True
    if p.life == LifeState.IN_VEHICLE:
        vehicle = match.vehicles.get(p.vehicle_id or "")
        return vehicle is None or vehicle.driver_id != p.participant_id
    return False


def _falloff(weapon: items.WeaponSpec, dist: float) -> float:
    if dist <= weapon.falloff_start:
        return 1.0
    span = max(weapon.range - weapon.falloff_start, 1e-6)
    t = min(1.0, (dist - weapon.falloff_start) / span)
    return 1.0 - t * (1.0 - weapon.min_damage_fraction)


def _pellet_chance(weapon: items.WeaponSpec, dist: float) -> float:
    if dist <= weapon.falloff_start:
        return 1.0
    span = max(weapon.range - weapon.falloff_start, 1e-6)
    return max(0.3, 1.0 - 0.7 * (dist - weapon.falloff_start) / span)


def mitigate(victim: Participant, raw: float, headshot: bool = False) -> float:
    """Apply helmet (headshot) or body armor reduction and wear. Returns the damage left."""
    if raw <= 0:
        return 0.0
    inv = victim.inventory
    if headshot:
        spec = items.HELMETS.get(inv.helmet_id or "")
        if spec is None or inv.helmet_durability <= 0:
            return raw
        inv.helmet_durability -= raw
        if inv.helmet_durability <= 0:
            inv.helmet_id, inv.helmet_durability = None, 0.0
        return raw * (1.0 - spec.reduction)
    spec = items.ARMORS.get(inv.armor_id or "")
    if spec is None or inv.armor_durability <= 0:
        return raw
    inv.armor_durability -= raw
    if inv.armor_durability <= 0:
        inv.armor_id, inv.armor_durability = None, 0.0
    return raw * (1.0 - spec.reduction)


def hit_chance(shooter: Participant, target: Participant, distance: float, accuracy: float) -> float:
    """Chance (0.02..0.98) a bot shot that is already in range and line of sight hits."""
    slot = _active(shooter)
    weapon = items.WEAPONS.get(slot.weapon_id) if slot else None
    chance = accuracy
    if weapon is not None:
        chance += items.accuracy_bonus(slot)
        if distance > weapon.falloff_start:
            span = max(weapon.range - weapon.falloff_start, 1e-6)
            chance *= 1.0 - 0.5 * min(1.0, (distance - weapon.falloff_start) / span)
    if target.stance == Stance.CROUCH:
        chance *= 0.85
    elif target.stance == Stance.PRONE:
        chance *= 0.7
    if abs(target.move_x) + abs(target.move_y) > 1e-6:
        chance *= 0.85
    if abs(shooter.move_x) + abs(shooter.move_y) > 1e-6:
        chance *= 0.9
    return max(0.02, min(0.98, chance))


# --------------------------------------------------------------------------- damage and elimination


def apply_damage(
    match: SoloMatch, victim: Participant, amount: float, attacker_id: str | None, cause: str
) -> float:
    """Remove health after mitigation. Returns the health actually removed."""
    if not victim.alive or not isinstance(amount, (int, float)) or not amount > 0:
        return 0.0
    actual = min(float(amount), victim.health)
    victim.health -= actual
    victim.stats.damage_taken += actual
    attacker = match.participants.get(attacker_id or "")
    if attacker is not None and attacker is not victim:
        attacker.stats.damage_dealt += actual
    if victim.healing_item is not None:
        victim.heal_left, victim.healing_item = 0.0, None
    match.emit(
        "damage",
        victim_id=victim.participant_id,
        attacker_id=attacker_id,
        amount=actual,
        cause=cause,
        health=victim.health,
    )
    if victim.health <= 1e-9:
        eliminate(match, victim, attacker_id, cause)
    return actual


def eliminate(match: SoloMatch, victim: Participant, killer_id: str | None, cause: str) -> None:
    """Idempotent. Marks the victim eliminated, credits the kill and drops a death crate."""
    if not victim.alive:
        return
    victim.life = LifeState.ELIMINATED
    victim.health = 0.0
    victim.eliminated_at = match.clock
    victim.eliminated_by = killer_id
    victim.eliminated_cause = cause
    victim.fire_cooldown = victim.reload_left = victim.heal_left = 0.0
    victim.healing_item = None
    killer = match.participants.get(killer_id or "")
    if killer is not None and killer is not victim:
        killer.stats.kills += 1
    if victim.participant_id not in match.elimination_order:
        match.elimination_order.append(victim.participant_id)
    vehicle = match.vehicles.get(victim.vehicle_id or "")
    if vehicle is not None:
        if vehicle.driver_id == victim.participant_id:
            vehicle.driver_id = None
        if victim.participant_id in vehicle.passenger_ids:
            vehicle.passenger_ids.remove(victim.participant_id)
    victim.vehicle_id = None
    _BOOST.get(_key(match), {}).pop(victim.participant_id, None)
    crate_id = loot.create_death_crate(match, victim)
    match.emit(
        "elimination",
        victim_id=victim.participant_id,
        killer_id=killer_id,
        cause=cause,
        crate_id=crate_id,
        alive=len(match.alive()),
    )


# --------------------------------------------------------------------------- firing


def fire(
    match: SoloMatch,
    shooter: Participant,
    aim_x: float,
    aim_y: float,
    target_id: str | None,
    roll: float | None = None,
    headshot: bool | None = False,
) -> tuple[bool, str]:
    """Fire one round from the active weapon toward the world point (aim_x, aim_y).

    ok=False means no round was fired. ok=True with detail "miss:<reason>" or "hit:<id>:<damage>".
    Bots pass roll in 0..1; humans pass None and an in-cone, in-range, visible target is a hit.
    headshot=None asks the server to roll it (HEADSHOT_SHARE of hits); a bool is trusted as is.
    """
    try:
        aim_x, aim_y = float(aim_x), float(aim_y)
    except (TypeError, ValueError):
        return False, "bad aim"
    if not (math.isfinite(aim_x) and math.isfinite(aim_y)):
        return False, "bad aim"
    if not _can_act(match, shooter):
        return False, "cannot fire now"
    slot = _active(shooter)
    weapon = items.WEAPONS.get(slot.weapon_id) if slot else None
    if slot is None or weapon is None:
        return False, "no weapon"
    if shooter.reload_left > 0:
        return False, "reloading"
    if shooter.healing_item is not None or shooter.heal_left > 0:
        return False, "healing"
    if shooter.fire_cooldown > 0:
        return False, "cooldown"
    if slot.mag <= 0:
        return False, "empty magazine"

    slot.mag -= 1
    shooter.fire_cooldown = weapon.fire_interval
    shooter.stats.shots_fired += 1
    match.emit("shot", shooter_id=shooter.participant_id, weapon_id=weapon.weapon_id, aim_x=aim_x, aim_y=aim_y)

    if not target_id:
        return True, "miss:no target"
    target = match.participants.get(target_id)
    if target is None or target is shooter or not target.alive or target.life not in _SHOOTABLE:
        return True, "miss:invalid target"
    dist = distance3d(shooter, target)
    if dist > weapon.range:
        return True, "miss:out of range"
    if not blocker_index(match.map).los(shooter.x, shooter.y, target.x, target.y):
        return True, "miss:blocked"
    ax, ay = normalize(aim_x - shooter.x, aim_y - shooter.y)
    if ax == 0.0 and ay == 0.0:
        ax, ay = math.cos(shooter.yaw), math.sin(shooter.yaw)
    tx, ty = normalize(target.x - shooter.x, target.y - shooter.y)
    if math.hypot(target.x - shooter.x, target.y - shooter.y) > 1e-6:
        angle = math.degrees(math.acos(max(-1.0, min(1.0, ax * tx + ay * ty))))
        if angle > items.cone_degrees(slot):
            return True, "miss:off aim"
    if roll is not None:
        try:
            roll = float(roll)
        except (TypeError, ValueError):
            roll = 1.0
        accuracy = shooter.brain.profile.aim_accuracy if shooter.brain is not None else 0.5
        chance = hit_chance(shooter, target, dist, accuracy)
        if not roll < chance:
            return True, "miss:roll"
        headshot = roll < chance * HEADSHOT_SHARE
    elif headshot is None:
        headshot = match.rng.random() < HEADSHOT_SHARE

    per_hit = weapon.damage * _falloff(weapon, dist)
    if headshot:
        per_hit *= weapon.headshot_multiplier
    hits = 1
    if weapon.pellets > 1:
        p_chance = _pellet_chance(weapon, dist)
        hits = sum(1 for _ in range(weapon.pellets) if p_chance >= 1.0 or match.rng.random() < p_chance)
        if hits == 0:
            return True, "miss:pellets"
    shooter.stats.shots_hit += 1
    dealt = 0.0
    for _ in range(hits):
        if not target.alive:
            break
        dealt += apply_damage(match, target, mitigate(target, per_hit, headshot), shooter.participant_id, weapon.weapon_id)
    return True, f"hit:{target.participant_id}:{dealt:.1f}"


# --------------------------------------------------------------------------- reload and heal


def start_reload(p: Participant) -> tuple[bool, str]:
    if not p.alive:
        return False, "eliminated"
    slot = _active(p)
    weapon = items.WEAPONS.get(slot.weapon_id) if slot else None
    if slot is None or weapon is None:
        return False, "no weapon"
    if p.reload_left > 0:
        return False, "already reloading"
    if slot.mag >= items.mag_capacity(slot):
        return False, "magazine full"
    if p.inventory.backpack.get(weapon.ammo_id, 0) <= 0:
        return False, "no ammo"
    p.heal_left, p.healing_item = 0.0, None
    p.reload_left = weapon.reload_seconds
    return True, "ok"


def start_heal(p: Participant, item_id: str) -> tuple[bool, str]:
    if not p.alive or p.life not in (LifeState.GROUNDED, LifeState.IN_VEHICLE):
        return False, "cannot heal now"
    spec = items.HEALS.get(item_id)
    if spec is None:
        return False, "not a heal"
    if p.inventory.backpack.get(item_id, 0) <= 0:
        return False, "not carried"
    if p.healing_item is not None:
        return False, "already healing"
    if p.reload_left > 0:
        return False, "reloading"
    if spec.boost <= 0 and p.health >= min(spec.cap, p.max_health):
        return False, "health above item cap"
    p.healing_item = item_id
    p.heal_left = spec.use_seconds
    return True, "ok"


def _finish_reload(match: SoloMatch, p: Participant) -> None:
    slot = _active(p)
    weapon = items.WEAPONS.get(slot.weapon_id) if slot else None
    if slot is None or weapon is None:
        return
    need = max(0, items.mag_capacity(slot) - slot.mag)
    have = p.inventory.backpack.get(weapon.ammo_id, 0)
    loaded = min(need, have)
    if loaded <= 0:
        match.emit("reload_failed", participant_id=p.participant_id)
        return
    if have - loaded <= 0:
        p.inventory.backpack.pop(weapon.ammo_id, None)
    else:
        p.inventory.backpack[weapon.ammo_id] = have - loaded
    slot.mag += loaded
    match.emit("reload", participant_id=p.participant_id, mag=slot.mag)


def _finish_heal(match: SoloMatch, p: Participant, item_id: str) -> None:
    spec = items.HEALS.get(item_id)
    have = p.inventory.backpack.get(item_id, 0)
    if spec is None or have <= 0:
        return
    if have == 1:
        p.inventory.backpack.pop(item_id, None)
    else:
        p.inventory.backpack[item_id] = have - 1
    cap = min(spec.cap, p.max_health)
    if p.health < cap:
        p.health = min(cap, p.health + spec.amount)
    if spec.boost > 0:
        boosts = _BOOST.setdefault(_key(match), {})
        boosts[p.participant_id] = min(100.0, boosts.get(p.participant_id, 0.0) + spec.boost)
    p.stats.heals_used += 1
    match.emit("heal", participant_id=p.participant_id, item_id=item_id, health=p.health)


def tick_timers(match: SoloMatch, p: Participant, dt: float) -> None:
    """Advance cooldown, reload, heal and boost timers for one participant."""
    if not p.alive or not isinstance(dt, (int, float)) or not dt > 0:
        return
    p.fire_cooldown = max(0.0, p.fire_cooldown - dt)
    # boost regenerates first, so boost granted this tick starts next tick
    boosts = _BOOST.get(_key(match))
    if boosts and boosts.get(p.participant_id, 0.0) > 0:
        spend = min(boosts[p.participant_id], BOOST_REGEN * dt)
        boosts[p.participant_id] -= spend
        p.health = min(p.max_health, p.health + spend)
    if p.reload_left > 0:
        p.reload_left -= dt
        if p.reload_left <= 0:
            p.reload_left = 0.0
            _finish_reload(match, p)
    if p.healing_item is not None:
        p.heal_left -= dt
        if p.heal_left <= 0:
            item_id = p.healing_item
            p.heal_left, p.healing_item = 0.0, None
            _finish_heal(match, p, item_id)


# --------------------------------------------------------------------------- grenades


def throw_grenade(match: SoloMatch, p: Participant, x: float, y: float, item_id: str = "frag") -> tuple[bool, str]:
    """Throw a carried grenade toward (x, y). Targets beyond 35 m are clamped to 35 m."""
    try:
        x, y = float(x), float(y)
    except (TypeError, ValueError):
        return False, "bad target"
    if not (math.isfinite(x) and math.isfinite(y)):
        return False, "bad target"
    spec = items.THROWABLES.get(item_id)
    if spec is None:
        return False, "not a throwable"
    if not p.alive or p.life != LifeState.GROUNDED:
        return False, "cannot throw now"
    if p.healing_item is not None or p.reload_left > 0:
        return False, "busy"
    if p.inventory.backpack.get(item_id, 0) <= 0:
        return False, "not carried"
    dist = distance(p.x, p.y, x, y)
    if dist > spec.max_range:
        dx, dy = normalize(x - p.x, y - p.y)
        x, y = p.x + dx * spec.max_range, p.y + dy * spec.max_range
    have = p.inventory.backpack[item_id]
    if have == 1:
        p.inventory.backpack.pop(item_id, None)
    else:
        p.inventory.backpack[item_id] = have - 1
    grenade = PendingGrenade(match.new_id("grenade"), p.participant_id, item_id, x, y, match.clock + spec.fuse_seconds)
    _GRENADES.setdefault(_key(match), []).append(grenade)
    match.emit("throw", participant_id=p.participant_id, item_id=item_id, grenade_id=grenade.grenade_id, x=x, y=y)
    return True, grenade.grenade_id


def tick_grenades(match: SoloMatch) -> None:
    """Explode every pending grenade whose fuse has run out at match.clock."""
    pending = _GRENADES.get(_key(match))
    if not pending:
        return
    due = [g for g in pending if g.explode_at <= match.clock]
    if not due:
        return
    pending[:] = [g for g in pending if g.explode_at > match.clock]
    for grenade in due:
        spec = items.THROWABLES.get(grenade.item_id)
        if spec is None:
            continue
        match.emit("explosion", grenade_id=grenade.grenade_id, item_id=grenade.item_id, x=grenade.x, y=grenade.y)
        if spec.damage <= 0:
            continue
        index = blocker_index(match.map)
        for victim in list(match.participants.values()):
            if not victim.alive or victim.life not in (LifeState.GROUNDED, LifeState.IN_VEHICLE):
                continue
            d = distance(grenade.x, grenade.y, victim.x, victim.y)
            if d > spec.radius:
                continue
            if not index.los(grenade.x, grenade.y, victim.x, victim.y):
                continue
            raw = spec.damage * (1.0 - d / spec.radius)
            apply_damage(match, victim, mitigate(victim, raw), grenade.owner_id, grenade.item_id)
